// Configure AGE 03 manually before each page; never run as a sender.
// Keyset page is sorted by Chatwoot recipient updated_at ASC, id ASC.
// For the first page use epoch/id zero; for next page paste nextCursor.
const p={chatwootAccountId:2,afterUpdatedAt:'1970-01-01T00:00:00.000Z',
  afterRowId:'0',pageSize:250};
if(!Number.isSafeInteger(p.chatwootAccountId)||p.chatwootAccountId<1)throw Error('INVALID_ACCOUNT_ID');
if(!Number.isSafeInteger(p.pageSize)||p.pageSize<1||p.pageSize>500)throw Error('INVALID_PAGE_SIZE');
if(!Number.isFinite(Date.parse(p.afterUpdatedAt))||!/Z$/.test(p.afterUpdatedAt))throw Error('CURSOR_MUST_BE_UTC_ISO');
if(!/^(0|[1-9]\d*)$/.test(String(p.afterRowId)))throw Error('CURSOR_ROW_ID_MUST_BE_DECIMAL');
return [{json:p}];

// AGE 03 read-only page inspection; no API calls/sends/CRM writes.
// In n8n, this output contains sensitive recipient identifiers: private execution only.
const raw=$input.all().map(x=>x.json||{});
const params=$('Configure Account and Keyset Cursor').first().json;
const limit=Number(params.pageSize);
const base={source:'CHATWOOT_POSTGRES_CURRENT_RECIPIENT_SNAPSHOT',mode:'READ_ONLY',
  checkedAt:new Date().toISOString(),chatwootAccountId:params.chatwootAccountId,
  requestedAfter:{updatedAt:params.afterUpdatedAt,rowId:String(params.afterRowId)},
  pageSize:limit,sends:0,espocrmWrites:0,dataTableWrites:0,
  mappingsVerified:false,providerProvenanceIndependentlyVerified:false,
  licensePermissionVerified:false,fullAttemptHistory:false};
if(raw.some(r=>r.error||r.message?.includes?.('permission denied'))){
  return [{json:{...base,status:'BLOCKED',reason:'POSTGRES_QUERY_FAILED_OR_ACCESS_DENIED',
    nextCursor:null,records:[],note:'Database access error: inspect node without copying any secrets.'}}];
}
const data=raw.filter(r=>r.recipient_row_id!==undefined&&r.recipient_row_id!==null);
if(raw.length>0&&data.length!==raw.filter(r=>Object.keys(r).length>0).length)
  return [{json:{...base,status:'BLOCKED',reason:'QUERY_RESPONSE_SCHEMA_MISMATCH',nextCursor:null,records:[]}}];
const hasMore=data.length>limit;
const page=data.slice(0,limit);
const warnings=[],records=[],seen=new Set();
const normalPhone=(s)=>{const v=String(s||'').trim();const digits=v.replace(/\D/g,'');
  return digits.length>=8&&digits.length<=15?digits:null;};
const numericString=(v)=>{const x=String(v??'');if(!/^[0-9]+$/.test(x))throw Error('INVALID_ID');return x;};
const time=(v)=>{if(!v)return null;const ms=Date.parse(String(v));
  return Number.isFinite(ms)?new Date(ms).toISOString():null;};
for(const r of page){
 const reasons=[];
 let id,contact,campaign,account,inbox,st;
 try {id=numericString(r.recipient_row_id);
   contact=numericString(r.contact_id);
   campaign=numericString(r.internal_campaign_id);
   account=numericString(r.account_id);
   inbox=numericString(r.inbox_id);
   st=Number(r.message_status);
 }catch(e){return [{json:{...base,status:'BLOCKED',reason:'INVALID_PRIMARY_KEY',records:[],nextCursor:null}}];}
 const key=account+'|'+campaign+'|'+id;
 if(seen.has(key))return [{json:{...base,status:'BLOCKED',reason:'DUPLICATED_RECIPIENT_ROW',records:[],nextCursor:null}}];
 seen.add(key);
 if(account!==String(params.chatwootAccountId))return [{json:{...base,status:'BLOCKED',reason:'ACCOUNT_MISMATCH',records:[],nextCursor:null}}];
 if(!Number.isInteger(st)||st<0||st>5)return [{json:{...base,status:'BLOCKED',reason:'INVALID_STATUS',records:[],nextCursor:null}}];
 const source=String(r.provider_message_id||'').trim();
 const formatValid=/^wamid\.[A-Za-z0-9_=.\-]+$/.test(source);
 const mobile=normalPhone(r.current_mobile_number);
 const at={sent:time(r.sent_at),delivered:time(r.delivered_at),
   read:time(r.read_at),failed:time(r.failed_at),updated:time(r.recipient_updated_at)};
 if(!at.updated)return [{json:{...base,status:'BLOCKED',reason:'INVALID_CURSOR_TIMESTAMP',records:[],nextCursor:null}}];
 if(!formatValid)reasons.push('MISSING_OR_INVALID_WAMID_FORMAT');
 if(!mobile)reasons.push('MISSING_CURRENT_MOBILE');
 if(st===4&&!at.read)reasons.push('MISSING_READ_TIMESTAMP');
 if(st===3&&!at.delivered)reasons.push('MISSING_DELIVERY_TIMESTAMP');
 // READ proves delivery even without a separate delivered_at event; never invent the time.
 if(st===5&&!at.failed)reasons.push('MISSING_FAILURE_TIMESTAMP');
 if(st===5&&!String(r.error_code||'').trim())reasons.push('MISSING_META_ERROR_CODE');
 // Meta may return a wamid for accepted messages that subsequently fail delivery.
 const states=['QUEUED','SKIPPED','SENT','DELIVERED','READ','FAILED'];
 const row={
  chatwootAccountId:account,chatwootCampaignInternalId:campaign,
  chatwootCampaignDisplayId:r.campaign_display_id,chatwootCampaignName:r.campaign_name,
  chatwootInboxId:inbox,chatwootContactId:contact,
  chatwootContactInboxId:r.contact_inbox_id==null?null:String(r.contact_inbox_id),
  chatwootRecipientRowId:id,currentMobileDigits:mobile,
  providerMessageId:source||null,providerIdFormatValid:formatValid,
  status:states[st],deliveredConfirmed:st===3||st===4,readConfirmed:st===4,
  timestamps:at,errorCode:r.error_code==null?null:String(r.error_code),
  errorTitle:r.error_title==null?null:String(r.error_title),
  errorMessage:r.error_message==null?null:String(r.error_message),
  candidateMatchKey:account+'|'+campaign+'|'+contact+'|'+source,
  mappingStatus:'UNMATCHED',espocrmCampaignId:null,espocrmRecipientId:null,
  espocrmAttemptId:null,canWriteEspocrm:false,
  evidenceSource:'CHATWOOT_CURRENT_STATE_NOT_PROVIDER_EVENT_LOG',
  warnings:reasons};
 if(reasons.length)warnings.push({recipientRowId:id,codes:reasons});
 records.push(row);
}
const last=page[page.length-1];
const cursor=last?{updatedAt:records[records.length-1].timestamps.updated,
  rowId:String(last.recipient_row_id)}:null;
const nextCursor=hasMore?cursor:null;
return [{json:{...base,status:warnings.length?'PARTIAL_EVIDENCE':'PAGE_READ',
  pageRecordCount:records.length,hasMore,nextCursor,lastPageCursor:cursor,
  truncatedByPageSize:hasMore,warningCount:warnings.length,warnings,
  records,note:'Recipient-level current snapshot for private n8n review; not yet matched to authoritative EspoCRM attempt IDs. Update Configure Account and Keyset Cursor to request next page. Never treat current contact mobile as historical sent-to proof.'}}];
